// Tests for vba:CairnForms.DocCustomerChanged (CairnForms L705-719).
//
// The function fires when a customer is picked on a quote/order form and
// syncs tax rate, rep, and primary contact. It reads Customers, CompanyInfo
// and Contacts via DLookup. We model the form as a struct and assume the
// rule function `doc_customer_changed(frm: &mut Form)` exists; we do not
// implement it.
//
// Data dependencies (verified against the live database):
//   CompanyInfo row 1: DefaultTaxRate = 0.0825
//   Customers: 1 -> taxexempt=1, assignedrepid=11
//              2 -> taxexempt=0, assignedrepid=1
//              6 -> taxexempt=1, assignedrepid=7
//              11 -> taxexempt=1, assignedrepid=11
//   Contacts (IsPrimary=True): 1->1, 2->2, 6->7, 11->17
//   Exactly one primary contact per customer (verified: no customer has
//   a primary count other than 1).

#[derive(Clone, Copy)]
struct Form {
    customer_id: Option<i32>, // Null in Access
    tax_rate: f64,
    rep_id: Option<i32>,      // Null in Access
    contact_id: Option<i32>,
}

fn form(customer_id: Option<i32>, tax_rate: f64, rep_id: Option<i32>, contact_id: Option<i32>) -> Form {
    Form { customer_id, tax_rate, rep_id, contact_id }
}

fn approx(a: f64, b: f64) -> bool {
    (a - b).abs() < 1e-9
}

// Rule 1 (L707-708): a Null CustomerID exits doing nothing.
#[test]
fn null_customer_changes_nothing() {
    let mut frm = form(None, 0.5, Some(99), Some(99));
    doc_customer_changed(&mut frm);
    assert!(approx(frm.tax_rate, 0.5));
    assert_eq!(frm.rep_id, Some(99));
    assert_eq!(frm.contact_id, Some(99));
}

// Rule 2 (L709-710): a tax-exempt customer gets taxRate = 0.
// Customer 1 is tax-exempt; rep null -> assigned rep 11; primary contact 1.
#[test]
fn tax_exempt_customer_gets_zero_rate() {
    let mut frm = form(Some(1), 0.0825, None, None);
    doc_customer_changed(&mut frm);
    assert!(approx(frm.tax_rate, 0.0));
    assert_eq!(frm.rep_id, Some(11));
    assert_eq!(frm.contact_id, Some(1));
}

// Rule 3 (L712): a non-exempt customer gets CompanyInfo.DefaultTaxRate.
// Customer 2 is not exempt -> 0.0825; rep null -> 1; primary contact 2.
#[test]
fn non_exempt_customer_gets_default_rate() {
    let mut frm = form(Some(2), 0.0, None, None);
    doc_customer_changed(&mut frm);
    assert!(approx(frm.tax_rate, 0.0825));
    assert_eq!(frm.rep_id, Some(1));
    assert_eq!(frm.contact_id, Some(2));
}

// Rule 4 (L714): rep is set only when currently Null; an existing rep is
// never overwritten. Customer 2's assigned rep is 1, but a pre-set rep 5
// must survive.
