fn valid_customer_overwrites_stale_caller_company() {
    let mut frm = PhoneMessageForm {
        customer_id: Some(1),
        caller_company: Some("Stale Company".to_string()),
        caller_phone: None,
    };
    message_customer_changed(&mut frm);
    assert_eq!(
