/// even when the selected customer has a different phone on file.
#[test]
fn existing_caller_phone_is_never_overwritten() {
    let mut frm = PhoneMessageForm {
        customer_id: Some(2),
        caller_company: None,
        caller_phone: Some("555-9999".to_string()),
