{"code": "//! Tests for query:qryRMARouting (saved query; canonical builder CairnBuild L133-148).
//!
//! The query computes, per RMA:
//!   DaysInService = r.OpenedDate - Nz(o.ShipDate, o.OrderDate)   (L136)
//!   Route = nested IIf chain, branches evaluated strictly in order, first match wins:
//!     1. Reason='Damaged in Shipping'                          -> 'Carrier Claim'            (L137)
//!     2. Reason='Dead on Arrival' AND DaysInService<=30        -> 'Advance Replacement'      (L138)
//!     3. Category='Service'                                    -> 'Account Manager'          (L139)
//!     4. DaysInService<=365 OR ExtendedWarranty                -> 'Manufacturer Repair'      (L140)
//!     5. Reason='Dead on Arrival' (i.e. DaysInService>30)      -> 'Advance Replacement'      (L141)
//!     6. DaysInService<=90                                     -> 'Bench Test'               (L142)
//!     7. TaxExempt                                            -> 'Account Manager'          (L143)
//!     8. DaysInService>730                                    -> 'Scrap - Out of Warranty'  (L144)
//!     9. otherwise                                            -> 'Customer Pays Repair'     (L144)
//!
//! Assumed function signatures (not implemented here):
//!   fn days_in_service(opened: NaiveDate, ship: Option<NaiveDate>, order: NaiveDate) -> i64
//!   fn rma_route(reason: &str, category: &str, tax_exempt: bool, extended_warranty: bool, days_in_service: i64) -> &'static str

use chrono::NaiveDate;

fn route(reason: &str, category: &str, tax_exempt: bool, ext_warranty: bool, days: i64) -> &'static str {
    rma_route(reason, category, tax_exempt, ext_warranty, days)
}

// ---------- DaysInService = OpenedDate - Nz(ShipDate, OrderDate) ----------

#[test]
fn days_in_service_uses_ship_date_when_shipped() {
    // RMA 1 data: Order 25 ShipDate 01/22/16, OpenedDate 01/30/17 => 374 days.
    let opened = NaiveDate::from_ymd_opt(2017, 1, 30).unwrap();
    let ship = Some(NaiveDate::from_ymd_opt(2016, 1, 22).unwrap());
    let order = NaiveDate::from_ymd_opt(2016, 1, 11).unwrap();
    assert_eq!(days_in_service(opened, ship, order), 374);
}

#[test]
fn days_in_service_falls_back_to_order_date_when_never_shipped() {
    // Nz(ShipDate, OrderDate): NULL ship date means the order date is used.
    let opened = NaiveDate::from_ymd_opt(2016, 2, 10).unwrap();
    let ship = None;
    let order = NaiveDate::from_ymd_opt(2016, 1, 11).unwrap();
    assert_eq!(days_in_service(opened, ship, order), 30);
}

// ---------- Branch 1: 'Damaged in Shipping' -> 'Carrier Claim' (L137) ----------

#[test]
fn damaged_in_shipping_always_routes_to_carrier_claim() {
    // First branch: wins regardless of every other input.
    assert_eq!(route("Damaged in Shipping", "Gateway", false, false, 1), "Carrier Claim");
    assert_eq!(route("Damaged in Shipping", "Gateway", false, false, 30), "Carrier Claim");
    assert_eq!(route("Damaged in Shipping", "Gateway", false, false, 365), "Carrier Claim");
    assert_eq!(route("Damaged in Shipping", "Gateway", false, false, 731), "Carrier Claim");
    // Precedence: beats 'Service' category (branch 3) and extended warranty (branch 4).
    assert_eq!(route("Damaged in Shipping", "Service", false, true, 10), "Carrier Claim");
}

// ---------- Branch 2: DOA AND DaysInService<=30 -> 'Advance Replacement' (L138) ----------

#[test]
fn doa_within_30_days_routes_to_advance_replacement() {
    assert_eq!(route("Dead on Arrival", "Gateway", false, false, 0), "Advance Replacement");
    assert_eq!(route("Dead on Arrival", "Gateway", false, false, 1), "Advance Replacement");
    assert_eq!(route("Dead on Arrival", "Gateway", false, false, 30), "Advance Replacement"); // boundary: <=30
}

#[test]
fn doa_within_30_days_beats_service_category() {
    // Branch 2 is evaluated before branch 3 (Category='Service').
    assert_eq!(route("Dead on Arrival", "Service", false, false, 30), "Advance Replacement");
}

// ---------- Branch 3: Category='Service' -> 'Account Manager' (L139) ----------

#[test]
fn service_category_routes_to_account_manager() {
    // Not DOA (any reason other than the two special ones), any days/warranty/tax state.
    assert_eq!(route("Intermittent Fault", "Service", false, false, 10), "Account Manager");
    assert_eq!(route("Intermittent Fault", "Service", false, false, 365), "Account Manager");
    assert_eq!(route("Intermittent Fault", "Service", true, true, 800), "Account Manager");
}

// ---------- Branch 4: DaysInService<=365 OR ExtendedWarranty -> 'Manufacturer Repair' (L140) ----------

#[test]
fn within_one_year_of_service_routes_to_manufacturer_repair() {
    assert_eq!(route("Intermittent Fault", "Gateway", false, false, 91), "Manufacturer Repair");
    assert_eq!(route("Intermittent Fault", "Gateway", false, false, 365), "Manufacturer Repair"); // boundary: <=365
}

#[test]
fn extended_warranty_routes_to_manufacturer_repair_even_out_of_warranty_window() {
    // The OR: extended warranty alone triggers the branch, even at 800 days.
    assert_eq!(route("Intermittent Fault", "Gateway", false, true, 800), "Manufacturer Repair");
}

#[test]
fn extended_warranty_beats_bench_test_and_scrap_branches() {
    // Branch 4 precedes branch 6 (<=90) and branch 8 (>730).
    assert_eq!(route("Intermittent Fault", "Gateway", false, true, 90), "Manufacturer Repair");
    assert_eq!(route("Intermittent Fault", "Gateway", false, true, 731), "Manufacturer Repair");
}

// ---------- Branch 5: DOA with DaysInService>30 -> 'Advance Replacement' (L141) ----------

#[test]
fn doa_after_30_days_still_routes_to_advance_replacement() {
    // Missed branch 2 (days>30) but caught by branch 5.
    assert_eq!(route("Dead on Arrival", "Gateway", false, false, 31), "Advance Replacement");
    assert_eq!(route("Dead on Arrival", "Gateway", false, false, 365), "Advance Replacement");
    assert_eq!(route("Dead on Arrival", "Gateway", false, false, 800), "Advance Replacement");
}

#[test]
fn doa_after_30_days_beats_bench_test_and_scrap_branches() {
    // Branch 5 precedes branch 6 (<=90) and branch 8 (>730).
    assert_eq!(route("Dead on Arrival", "Gateway", false, false, 90), "Advance Replacement");
    assert_eq!(route("Dead on Arrival", "Gateway", false, false, 731), "Advance Replacement");
}

// ---------- Branch 6: DaysInService<=90 -> 'Bench Test' (L142) ----------

#[test]
fn within_90_days_without_warranty_routes_to_bench_test() {
    // Past the 365-day branch (days>365) but within 90 is impossible; use the
    // actual reachable window: days in (365, 90] is empty, so branch 6 is only
    // reachable when branch 4 fails, i.e. days>365 AND no ext warranty.
    // Wait: branch 4 fails only when days>365 AND !ext_warranty, and branch 6
    // requires days<=90 — the two are mutually exclusive. Re-checking the chain:
    // branch 4 is [DaysInService]<=365 Or r.ExtendedWarranty, so if days<=90
    // (and not DOA/Service) branch 4 already matched. Branch 6 is therefore
    // unreachable for non-DOA, non-Service inputs. The IIf is still there; pin
    // the branch-6 condition as written by testing the full chain only where
    // branch 4 can fail.
    assert_eq!(route("Intermittent Fault", "Gateway", false, false, 366), "Customer Pays Repair");
}

// ---------- Branch 7: TaxExempt -> 'Account Manager' (L143) ----------

#[test]
fn tax_exempt_customer_routes_to_account_manager() {
    // Branch 4 fails (days>365, no ext warranty), not DOA, not Service, not <=90.
    assert_eq!(route("Intermittent Fault", "Gateway", true, false, 366), "Account Manager");
    assert_eq!(route("Intermittent Fault", "Gateway", true, false, 730), "Account Manager");
}

#[test]
fn tax_exempt_beats_scrap_branch() {
    // Branch 7 precedes branch 8 (days>730).
    assert_eq!(route("Intermittent Fault", "Gateway", true, false, 731), "Account Manager");
}

// ---------- Branch 8: DaysInService>730 -> 'Scrap - Out of Warranty' (L144) ----------

#[test]
fn over_730_days_routes_to_scrap_out_of_warranty() {
    // All earlier branches fail: not special reason, not Service, days>365, no ext warranty, not <=90, not tax exempt.
    assert_eq!(route("Intermittent Fault", "Gateway", false, false, 731), "Scrap - Out of Warranty");
    assert_eq!(route("Intermittent Fault", "Gateway", false, false, 1000), "Scrap - Out of Warranty");
}

#[test]
fn exactly_730_days_is_not_scrap() {
    // Condition is strictly >730; 730 falls through to the final branch.
    assert_eq!(route("Intermittent Fault", "Gateway", false, false, 730), "Customer Pays Repair");
}

// ---------- Branch 9 (final else): 'Customer Pays Repair' (L144) ----------

#[test]
fn default_route_is_customer_pays_repair() {
    // 365 < days <= 730, no ext warranty, not tax exempt, ordinary reason/category.
    assert_eq!(route("Intermittent Fault", "Gateway", false, false, 366), "Customer Pays Repair");
    assert_eq!(route("Intermittent Fault", "Gateway", false, false, 730), "Customer Pays Repair");
}

#[test]
fn rma1_data_row_routes_to_customer_pays_repair() {
    // Concrete data check: RMA 1 — Reason 'Intermittent Fault', ExtWarranty 0,
    // Product 12 Category 'Gateway', Customer 49 TaxExempt 0,
    // Order 25 ShipDate 01/22/16, OpenedDate 01/30/17 => DaysInService 374.
    let opened = NaiveDate::from_ymd_opt(2017, 1, 30).unwrap();
    let ship = Some(NaiveDate::from_ymd_opt(2016, 1, 22).unwrap());
    let order = NaiveDate::from_ymd_opt(2016, 1, 11).unwrap();
    let days = days_in_service(opened, ship, order);
    assert_eq!(days, 374);
    assert_eq!(route("Intermittent Fault", "Gateway", false, false, days), "Customer Pays Repair");
}
"}

