}

// 12. followupdate nullable: NULL accepted (rows 1,2,5), a timestamp accepted (row 6: 2026-10-21).
#[test]
fn followupdate_nullable() {
    let mut a = act(1, None, 1, "Note", "x", false);
    a.followupdate = None;
    assert!(insert_activity(&a).is_ok());
